function mixHex(a: string, b: string, t: number) {
  const parse = (h: string) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(h.trim());
    if (!m) return null;
    const n = Number.parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const pa = parse(a);
  const pb = parse(b);
  if (!pa || !pb) return a;
  const c = pa.map((v, i) => Math.round(v + (pb[i] - v) * t));
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const EDGE = 0.045;

type Drawn = El & {
  kind: "struct" | "box" | "content" | "bg";
  /** Position along the sweep axis, 0..1. */
  at: number;
};

/** Center of an element along the "to bottom right" axis, 0..1. */
function diag(e: El) {
  let cx: number;
  let cy: number;
  if (e.t === "r") {
    cx = e.x + e.w / 2;
    cy = e.y + e.h / 2;
  } else if (e.t === "c") {
    cx = e.x;
    cy = e.y;
  } else if (e.t === "l") {
    cx = (e.x + e.x2) / 2;
    cy = (e.y + e.y2) / 2;
  } else if (e.t === "logo") {
    cx = e.x + e.size * 1.9;
    cy = e.y - e.size * 0.38;
  } else {
    cx = e.pts[Math.floor(e.pts.length / 2)][0];
    cy = e.pts[Math.floor(e.pts.length / 2)][1];
  }
  return (cx / VW + cy / VH) / 2;
}

function choreograph(): Drawn[] {
  return dashboard().map((e) => {
    const at = diag(e);
    const long =
      e.t === "l" && Math.abs(e.x2 - e.x) + Math.abs(e.y2 - e.y) > 600;
    if (e.t === "r" && e.f === "side") return { ...e, kind: "bg", at };
    if (long) return { ...e, kind: "struct", at };
    if (e.t === "r" && e.f === "card") return { ...e, kind: "box", at };
    return { ...e, kind: "content", at };
  });
}

const ELS = choreograph();

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function WireframeToFinalBase(props: WireframeToFinalProps) {
  const {
    src,
    theme = "light",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = mono,
    glow = 1,
    scale = 1,
    delay = 0,
    speed = 1,
    captions = ["Idea", "Product"],
    measurements = ["1440", "900", "288"],
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    wireframeToFinalTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const gridEl = tl.get("grid");
  const outline = tl.get("outline");
  const dims = tl.get("dims");
  const structure = tl.get("structure");
  const boxes = tl.get("boxes");
  const content = tl.get("content");
  const captionEl = tl.get("caption");
  const pushEl = tl.get("push");
  const sweepEl = tl.get("sweep");
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const P = PALETTE[theme];
  const stage =
    background === "transparent" ? "transparent" : (background ?? P.stage);
  const paper =
    background === undefined || background === "transparent"
      ? P.stage
      : background;
  const sweepAt = sweepEl.start;
  const sweepEnd = sweepEl.end;
  const dark = theme === "dark";
  const k = width / 1280;
  const W = Math.round(width * 0.64);
  const H = Math.round(W * (VH / VW));
  const left = (width - W) / 2;
  const top = (height - H) / 2 - 10 * k;
  const s = W / VW;
  const line = dark ? mixHex(accent, "#FFFFFF", 0.3) : accent;
  const clamp = {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  } as const;

  const draw = (start: number, dur: number) =>
    interpolate(frame, [start, start + dur], [0, 1], { ...clamp, easing: OUT });

  // Fill sweep front along the "to bottom right" axis.
  const front = interpolate(
    frame,
    [sweepAt, sweepEnd],
    [-0.02, 1 + EDGE + 0.02],
    {
      ...clamp,
      easing: INOUT,
    },
  );
  const sweepLife = interpolate(
    frame,
    [
      sweepAt,
      sweepAt + sweepEl.beat("fade"),
      sweepEnd - sweepEl.beat("fade"),
      sweepEnd,
    ],
    [0, 1, 1, 0],
    clamp,
  );
  const after = interpolate(
    frame,
    [sweepEnd - sweepEl.beat("lead"), sweepEnd + sweepEl.beat("tail")],
    [0, 1],
    {
      ...clamp,
      easing: INOUT,
    },
  );
  const pushAt = (f: number) =>
    interpolate(f, [pushEl.start, pushEl.end], [1, 1.05], {
      ...clamp,
      easing: INOUT,
    });
  const push = pushAt(frame);
  // The slow in-out push creeps at its start; weigh each step by how far
  // the furthest text sits from the origin.
  const pushing =
    Math.abs(pushAt(frame + speed) - push) * width * 0.6 > 1e-3 ||
    Math.abs(push - pushAt(frame - speed)) * width * 0.6 > 1e-3;
  const gridIn = interpolate(
    frame,
    [gridEl.start, gridEl.end],
    [0.55, 1],
    clamp,
  );
  const drift = interpolate(frame, [sweepAt, pushEl.end], [0, 1], clamp);
  const gridOp = gridIn * (1 - after * 0.55);
  const guides = 1 - after;

  const cropIn = interpolate(frame, [gridEl.start, gridEl.end], [0.45, 1], {
    ...clamp,
    easing: OUT,
  });
  const filled = (t: number) => Math.min(1, Math.max(0, (front - t) / EDGE));
  const frameDraw = draw(outline.start, outline.length);
  const dimDraw = draw(dims.start, dims.length);
  const labelIn = interpolate(
    frame,
    [dims.start + dims.beat("labelAt"), dims.start + dims.beat("labelEnd")],
    [0, 1],
    clamp,
  );

  const maskStop = (front - EDGE) * 100;
  const mask = `linear-gradient(to bottom right, #000 ${maskStop}%, transparent ${front * 100}%)`;
  const gid = `${uid}-area`;
  const clipId = `${uid}-clip`;
  const radius = 28 * s;
  const tone = (f?: Tone) =>
    f === "accent" || f === "accentSoft" ? accent : f ? P[f] : "none";

  // Sweep front: the line x/W + y/H = 2 * (front - EDGE / 2).
  const fl = 2 * (front - EDGE / 2);
  const fx1 = fl * W + W;
  const fy1 = -H;
  const fx2 = fl * W - 2 * W;
  const fy2 = 2 * H;

  const capSwap = interpolate(
    frame,
    [
      sweepAt + sweepEl.beat("capAt"),
      sweepAt + sweepEl.beat("capAt") + sweepEl.beat("cap"),
    ],
    [0, 1],
    {
      ...clamp,
      easing: INOUT,
    },
  );
  const capIn = interpolate(
    frame,
    [captionEl.start, captionEl.end],
    [0, 1],
    clamp,
  );
  // Each drawn piece's window: cards and content spread across their element
  // by their place along the diagonal.
  const spanOf = (e: Drawn) => {
    if (e.kind === "struct") return [structure.start, structure.length];
    if (e.kind === "box")
      return [
        boxes.start + e.at * (boxes.length - boxes.beat("box")),
        boxes.beat("box"),
      ];
    return [
      content.start + e.at * (content.length - content.beat("item")),
      e.t === "p" ? content.beat("path") : content.beat("item"),
    ];
  };

  const tick = 6 * k;
  const gap = 26 * k;
  const label = {
    fontFamily,
    fontSize: 11 * k,
    fill: line,
    letterSpacing: "0.04em",
  } as const;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <Grid
        width={width}
        height={height}
        k={k}
        P={stage === P.stage ? P : { ...P, stage }}
        uid={uid}
        opacity={gridOp}
      />
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${push})${glide(pushing)}`,
            transformOrigin: "50% 48%",
          }}
        >
          {/* pixel-glass underglow: the finished screen sits on a band of colour */}
          <div
            style={{
              position: "absolute",
              left: left + W * 0.06,
              top: top + H * 0.18,
              width: W * 0.88,
              height: H * 0.8,
              borderRadius: radius * 3,
              background: `linear-gradient(${100 + drift * 14}deg, ${GLASS[0]} 0%, ${GLASS[1]} 50%, ${GLASS[2]} 100%)`,
              filter: `blur(${70 * k}px)`,
              opacity: after * (dark ? 0.5 : 0.42) * glow,
              transform: `translateY(${(30 + 10 * after) * k}px)`,
            }}
          />
          {/* contact shadow, grows in once the screen is real */}
          <div
            style={{
              position: "absolute",
              left,
              top,
              width: W,
              height: H,
              borderRadius: radius,
              opacity: after,
              boxShadow: dark
                ? `0 0 0 1px rgba(255,255,255,0.09), 0 ${40 * k}px ${90 * k}px -${20 * k}px rgba(0,0,0,0.8)`
                : `0 0 0 1px rgba(20,20,24,0.07), 0 ${36 * k}px ${80 * k}px -${24 * k}px rgba(60,45,20,0.24), 0 ${4 * k}px ${12 * k}px -${4 * k}px rgba(60,45,20,0.08)`,
            }}
          />
          {/* final render, revealed by the diagonal sweep */}
          <div
            style={{
              position: "absolute",
              left,
              top,
              width: W,
              height: H,
              borderRadius: radius,
              overflow: "hidden",
              WebkitMaskImage: mask,
              maskImage: mask,
              background: P.pane,
            }}
          >
            {src ? (
              <Img
                src={src}
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            ) : null}
          </div>
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", left, top, overflow: "visible" }}
          >
            <title>Wireframe</title>
            <defs>
              <linearGradient id={gid} x1="0" y1="0" x2="1" y2="0">
                {GLASS.map((c, i) => (
                  <stop key={c} offset={i / (GLASS.length - 1)} stopColor={c} />
                ))}
              </linearGradient>
              <linearGradient id={`${gid}-fade`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#FFFFFF" stopOpacity={0.3} />
                <stop offset="1" stopColor="#FFFFFF" stopOpacity={0} />
              </linearGradient>
              <mask id={`${gid}-mask`} maskContentUnits="objectBoundingBox">
                <rect width={1} height={1} fill={`url(#${gid}-fade)`} />
              </mask>
              <clipPath id={clipId}>
                <rect width={W} height={H} rx={radius} />
              </clipPath>
            </defs>

            {/* final fills, region by region */}
            {src ? null : (
              <g clipPath={`url(#${clipId})`}>
                {ELS.map((e, i) => {
                  const op = filled(e.at);
                  if (op <= 0) return null;
                  const key = `f${i}`;
                  if (e.t === "l")
                    return (
                      <line
                        key={key}
                        x1={e.x * s}
                        y1={e.y * s}
                        x2={e.x2 * s}
                        y2={e.y2 * s}
                        stroke={P.hair}
                        opacity={op}
                      />
                    );
                  if (e.t === "c")
                    return (
                      <circle
                        key={key}
                        cx={e.x * s}
                        cy={e.y * s}
                        r={e.r * s}
                        fill={tone(e.f)}
                        opacity={op}
                      />
                    );
                  if (e.t === "logo") {
                    const rh = e.size * 0.76 * s;
                    return (
                      <g key={key} opacity={op}>
                        <path
                          d={REMOCN_R_PATH}
                          fill={P.logo}
                          transform={`translate(${e.x * s} ${e.y * s - rh}) scale(${rh / 134.26})`}
                        />
                        <text
                          x={e.x * s + rh * R_ASPECT + e.size * 0.04 * s}
                          y={e.y * s}
                          fill={P.logo}
                          style={{
                            fontFamily: manrope.fontFamily,
                            fontWeight: 600,
                            fontSize: e.size * s,
                            letterSpacing: "-0.025em",
                          }}
                        >
                          emocn
                        </text>
                      </g>
                    );
                  }
                  if (e.t === "p") {
                    const pts = e.pts.map(
                      ([x, y]) => [x * s, y * s] as [number, number],
                    );
                    const d = smooth(pts);
                    const base = 650 * s;
                    return (
                      <g key={key} opacity={op}>
                        <path
                          d={`${d} L ${pts[pts.length - 1][0]} ${base} L ${pts[0][0]} ${base} Z`}
                          fill={`url(#${gid})`}
                          mask={`url(#${gid}-mask)`}
                        />
                        <path
                          d={d}
                          fill="none"
                          stroke={`url(#${gid})`}
                          strokeWidth={Math.max(1.5, 3.4 * s)}
                          strokeLinecap="round"
                        />
                      </g>
                    );
                  }
                  return (
                    <rect
                      key={key}
                      x={e.x * s}
                      y={e.y * s}
                      width={e.w * s}
                      height={e.h * s}
                      rx={(e.r ?? 0) * s}
                      fill={tone(e.f)}
                      fillOpacity={e.f === "accentSoft" ? 0.16 : 1}
                      stroke={e.s ? P.hair : "none"}
                      opacity={op}
                    />
                  );
                })}
              </g>
            )}

            {/* blueprint linework */}
            <g fill="none" stroke={line} strokeWidth={1}>
              <rect
                x={0.5}
                y={0.5}
                width={W - 1}
                height={H - 1}
                rx={radius}
                pathLength={1}
                strokeDasharray="1 1"
                strokeDashoffset={1 - frameDraw}
                opacity={0.9 * (1 - after)}
              />
              {ELS.map((e, i) => {
                if (e.kind === "bg") return null;
                const [start, dur] = spanOf(e);
                const p = draw(start, dur);
                if (p <= 0) return null;
                const op =
                  (e.kind === "content" ? 0.75 : 0.9) *
                  (1 - Math.min(1, Math.max(0, (front - e.at) / (EDGE * 1.6))));
                if (op <= 0.01) return null;
                const key = `b${i}`;
                const common = {
                  pathLength: 1,
                  strokeDasharray: "1 1",
                  strokeDashoffset: 1 - p,
                  opacity: op,
                };
                if (e.t === "l")
                  return (
                    <line
                      {...common}
                      x1={e.x * s}
                      y1={e.y * s}
                      x2={e.x2 * s}
                      y2={e.y2 * s}
                    />
                  );
                if (e.t === "c")
                  return (
                    <circle
                      key={key}
                      {...common}
                      cx={e.x * s}
                      cy={e.y * s}
                      r={e.r * s}
                    />
                  );
                if (e.t === "logo") {
                  const rh = e.size * 0.76 * s;
                  const xh = e.size * 0.555 * s;
                  const tx = e.x * s + rh * R_ASPECT + e.size * 0.06 * s;
                  return (
                    <g key={key}>
                      <path
                        {...common}
                        d={REMOCN_R_PATH}
                        vectorEffect="non-scaling-stroke"
                        transform={`translate(${e.x * s} ${e.y * s - rh}) scale(${rh / 134.26})`}
                      />
                      <rect
                        {...common}
                        x={tx}
                        y={e.y * s - xh}
                        width={e.size * 3.02 * s}
                        height={xh}
                        rx={xh / 2}
                      />
                    </g>
                  );
                }
                if (e.t === "p")
                  return (
                    <path
                      {...common}
                      d={smooth(
                        e.pts.map(
                          ([x, y]) => [x * s, y * s] as [number, number],
                        ),
                      )}
                    />
                  );
                return (
                  <rect
                    key={key}
                    {...common}
                    x={e.x * s + 0.5}
                    y={e.y * s + 0.5}
                    width={Math.max(0, e.w * s - 1)}
                    height={Math.max(0, e.h * s - 1)}
                    rx={(e.r ?? 0) * s}
                  />
                );
              })}
            </g>

            {/* sweep front */}
            <g clipPath={`url(#${clipId})`} opacity={sweepLife}>
              <line
                x1={fx1}
                y1={fy1}
                x2={fx2}
                y2={fy2}
                stroke={line}
                strokeWidth={1.25}
              />
            </g>

            {/* measurements, crop marks and column ticks */}
            <g opacity={guides} stroke={line} strokeWidth={1} fill="none">
              {[
                [0, 0, -1, -1],
                [W, 0, 1, -1],
                [0, H, -1, 1],
                [W, H, 1, 1],
              ].map(([x, y, dx, dy]) => {
                const o = 10 * k;
                const L = 16 * k * cropIn;
                return (
                  <path
                    key={`crop-${x}-${y}`}
                    d={`M ${x + dx * o} ${y + dy * (o + L)} L ${x + dx * o} ${y + dy * o} L ${x + dx * (o + L)} ${y + dy * o}`}
                    opacity={0.7}
                  />
                );
              })}
              <g opacity={0.85}>
                <line x1={0} y1={-gap} x2={W * dimDraw} y2={-gap} />
                <line x1={0} y1={-gap - tick} x2={0} y2={-gap + tick} />
                <line
                  x1={W}
                  y1={-gap - tick}
                  x2={W}
                  y2={-gap + tick}
                  opacity={dimDraw >= 0.99 ? 1 : 0}
                />
                <line x1={-gap} y1={0} x2={-gap} y2={H * dimDraw} />
                <line x1={-gap - tick} y1={0} x2={-gap + tick} y2={0} />
                <line
                  x1={-gap - tick}
                  y1={H}
                  x2={-gap + tick}
                  y2={H}
                  opacity={dimDraw >= 0.99 ? 1 : 0}
                />
                <line x1={0} y1={H + gap} x2={288 * s * dimDraw} y2={H + gap} />
                <line x1={0} y1={H + gap - tick} x2={0} y2={H + gap + tick} />
                <line
                  x1={288 * s}
                  y1={H + gap - tick}
                  x2={288 * s}
                  y2={H + gap + tick}
                  opacity={dimDraw >= 0.99 ? 1 : 0}
                />
              </g>
              {Array.from({ length: 13 }, (_, c) => {
                const x = (288 + (c * (VW - 288)) / 12) * s;
                const on = draw(
                  dims.start + dims.beat("tickAt") + c * dims.beat("tick"),
                  dims.beat("tickDraw"),
                );
                return (
                  <line
                    key={`col-${c}`}
                    x1={x}
                    y1={-4 * k}
                    x2={x}
                    y2={-4 * k - 5 * k * on}
                    opacity={0.55 * on}
                  />
                );
              })}
            </g>
            <g opacity={guides * labelIn} style={label} stroke="none">
              <rect
                x={W / 2 - 24 * k}
                y={-gap - 8 * k}
                width={48 * k}
                height={16 * k}
                fill={paper}
              />
              <text x={W / 2} y={-gap + 4 * k} textAnchor="middle" fill={line}>
                {measurements[0]}
              </text>
              <rect
                x={-gap - 8 * k}
                y={H / 2 - 20 * k}
                width={16 * k}
                height={40 * k}
                fill={paper}
              />
              <text
                x={-gap + 4 * k}
                y={H / 2}
                textAnchor="middle"
                fill={line}
                transform={`rotate(-90 ${-gap + 4 * k} ${H / 2})`}
              >
                {measurements[1]}
              </text>
              <rect
                x={144 * s - 18 * k}
                y={H + gap - 8 * k}
                width={36 * k}
                height={16 * k}
                fill={paper}
              />
              <text
                x={144 * s}
                y={H + gap + 4 * k}
                textAnchor="middle"
                fill={line}
              >
                {measurements[2]}
              </text>
            </g>
          </svg>
        </AbsoluteFill>
        <Caption
          captions={captions}
          swap={capSwap}
          opacity={capIn}
          x={left + W}
          y={top + H + 18 * k}
          k={k}
          ink={ink ?? P.ink}
          accent={line}
          fontFamily={fontFamily}
        />
      </ScaleLayer>
    </AbsoluteFill>
  );
}

function Caption({
  captions,
  swap,
  opacity,
  x,
  y,
  k,
  ink,
  accent,
  fontFamily,
}: {
  captions: [string, string];
  swap: number;
  opacity: number;
  x: number;
  y: number;
  k: number;
  ink: string;
  accent: string;
  fontFamily: string;
}) {
  const glide = useGlide();
  if (!captions[0] && !captions[1]) return null;
  const row = (n: number, text: string, p: number) => (
    <div
      style={{
        position: "absolute",
        right: 0,
        top: 0,
        display: "flex",
        gap: 10 * k,
        whiteSpace: "nowrap",
        opacity: p,
        transform: `translateY(${(1 - p) * (n === 1 ? -8 : 8) * k}px)${glide(midway(p))}`,
      }}
    >
      <span style={{ color: accent }}>{`0${n + 1}`}</span>
      <span>{text}</span>
    </div>
  );
  return (
    <div
      style={{
        position: "absolute",
        left: x - 300 * k,
        top: y,
        width: 300 * k,
        height: 16 * k,
        fontFamily,
        fontSize: 11 * k,
        letterSpacing: "0.08em",
        textTransform: "uppercase",
        color: ink,
        opacity,
      }}
    >
      {row(0, captions[0], 1 - swap)}
      {row(1, captions[1], swap)}
    </div>
  );
}

function Grid({
  width,
  height,
  k,
  P,
  uid,
  opacity,
}: {
  width: number;
  height: number;
  k: number;
  P: (typeof PALETTE)["light"];
  uid: string;
  opacity: number;
}) {
  const minor = 24 * k;
  const major = minor * 5;
  const id = `${uid}-grid`;
  const idM = `${uid}-gridm`;
  const fade = `${uid}-fade`;
  return (
    <svg
      width={width}
      height={height}
      style={{ position: "absolute", inset: 0, opacity }}
    >
      <title>Grid</title>
      <defs>
        <pattern
          id={id}
          width={minor}
          height={minor}
          patternUnits="userSpaceOnUse"
          x={width / 2}
          y={height / 2}
        >
          <path
            d={`M ${minor} 0 L 0 0 0 ${minor}`}
            fill="none"
            stroke={P.grid}
            strokeWidth={1}
          />
        </pattern>
        <pattern
          id={idM}
          width={major}
          height={major}
          patternUnits="userSpaceOnUse"
          x={width / 2}
          y={height / 2}
        >
          <path
            d={`M ${major} 0 L 0 0 0 ${major}`}
            fill="none"
            stroke={P.gridMajor}
            strokeWidth={1}
          />
        </pattern>
        <radialGradient id={fade} cx="50%" cy="50%" r="65%">
          <stop offset="0.55" stopColor={P.stage} stopOpacity={0} />
          <stop offset="1" stopColor={P.stage} stopOpacity={1} />
        </radialGradient>
      </defs>
      <rect width={width} height={height} fill={`url(#${id})`} />
      <rect width={width} height={height} fill={`url(#${idM})`} />
      <rect width={width} height={height} fill={`url(#${fade})`} />
    </svg>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "light",
    variants: {
      light: {},
      dark: {},
    },
    description: "Theme",
  },
  sweep: {
    type: "number",
    default: 48,
    min: 12,
    max: 96,
    step: 2,
    description: "Sweep (frames)",
    hiddenFromList: false,
  },
  glow: {
    type: "number",
    default: 1,
    min: 0,
    max: 2,
    step: 0.1,
    description: "Glow",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "IBM Plex Mono",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","sweep","glow","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "light",
  sweep: 48,
  glow: 1,
  accent: "#3B5BFD",
  fontFamily: "IBM Plex Mono",
  scale: 1,
  delay: 0,
  speed: 1,
};

type WireframeToFinalElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WireframeToFinalBase>;

const WireframeToFinalInner = forwardRef<
  HTMLDivElement,
  WireframeToFinalElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WireframeToFinal>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WireframeToFinalBase
          {...(componentProps as unknown as ComponentProps<typeof WireframeToFinalBase>)}
        />
      </div>
    </Sequence>
  );
});

export const WireframeToFinal = Interactive.withSchema({
  Component: WireframeToFinalInner,
  componentName: "<WireframeToFinal>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
